[CmdletBinding(SupportsShouldProcess=$true)]
param([ValidateSet('Start','Continue','Status','Summarize','Stop')][string]$Action='Status',[ValidateRange(1,20)][int]$RunsPerArm=5,[ValidateRange(30,600)][int]$SampleSeconds=120,[ValidateRange(1,10)][int]$SampleIntervalSeconds=2,[switch]$AllowAutomaticReboot,[string]$EvidenceRoot="$PSScriptRoot\lab-evidence",[string]$RunDirectory,[string]$ProviderPath="$PSScriptRoot\..\..\controller\providers\HPTechPulseSmartHealthService.ps1")
Set-StrictMode -Version 2.0;$ErrorActionPreference='Stop';$TaskName='Lacksan-EXP-075-LabHarness';$ActivePointer=Join-Path $EvidenceRoot 'active.json'
function Elev{$p=New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent());if(-not$p.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)){throw 'Elevation required'}}
function Dir($p){if(-not(Test-Path -LiteralPath $p)){New-Item -ItemType Directory -Path $p -Force|Out-Null}};function WJ($p,$v){$v|ConvertTo-Json -Depth 12|Set-Content $p -Encoding UTF8};function RJ($p){if(-not(Test-Path $p)){throw "Required state missing: $p"};Get-Content $p -Raw|ConvertFrom-Json}
function Med($v){$a=@($v|?{$null-ne$_}|%{[double]$_}|sort);if(!$a.Count){return $null};$m=[int][math]::Floor($a.Count/2);if($a.Count%2){return$a[$m]};($a[$m-1]+$a[$m])/2};function Mad($v){$a=@($v|?{$null-ne$_}|%{[double]$_});if(!$a.Count){return $null};$m=Med $a;Med @($a|%{[math]::Abs($_-$m)})}
function P($d){[pscustomobject]@{State=Join-Path $d 'harness-state.json';ProviderState=Join-Path $d 'provider-state.json';ProviderLog=Join-Path $d 'provider-events.jsonl';Summary=Join-Path $d 'summary.json'}};function RD{if($RunDirectory){return(Resolve-Path $RunDirectory).Path};$a=RJ $ActivePointer;(Resolve-Path ([string]$a.runDirectory)).Path};function Prov($a,$d){$p=P $d;& $ProviderPath -Action $a -StatePath $p.ProviderState -LogPath $p.ProviderLog};function Boot{((Get-CimInstance Win32_OperatingSystem).LastBootUpTime).ToUniversalTime()}
function Protected{$sv=@();foreach($n in 'Tailscale','TermService','WinDefend','mpssvc','wuauserv'){try{$s=Get-Service $n -EA Stop;$sv+=[pscustomobject]@{name=$n;status="$($s.Status)";startType="$($s.StartType)"}}catch{$sv+=[pscustomobject]@{name=$n;status='absent'}}};[pscustomobject]@{services=$sv;processes=@(Get-Process -EA SilentlyContinue|?{$_.ProcessName-match'(?i)tailscale|msrdc|windowsapp|omnissa|horizon|vmware-view|wswc'}|select ProcessName,Id,Responding)}}
function Sys{[pscustomobject]@{cpu=[double](Get-CimInstance Win32_PerfFormattedData_PerfOS_Processor -Filter "Name='_Total'").PercentProcessorTime;disk=[double](Get-CimInstance Win32_PerfFormattedData_PerfDisk_PhysicalDisk -Filter "Name='_Total'").DiskBytesPersec}}
function Svc{$s=Get-CimInstance Win32_Service|?{$_.PathName-match'(?i)HP TechPulse SmartHealth\\hptpsmarthealth\.exe'};if(@($s).Count-ne1){throw 'Exact SmartHealth service unavailable'};$p=$null;if([int]$s.ProcessId-gt0){$g=Get-Process -Id $s.ProcessId -EA SilentlyContinue;$w=Get-CimInstance Win32_Process -Filter "ProcessId=$($s.ProcessId)" -EA SilentlyContinue;if($g-and$w){$p=[pscustomobject]@{pid=$s.ProcessId;cpuMs=$g.TotalProcessorTime.TotalMilliseconds;readBytes=$w.ReadTransferCount;writeBytes=$w.WriteTransferCount}}};[pscustomobject]@{name=$s.Name;startMode=$s.StartMode;state=$s.State;process=$p}}
function Collect($ph,$n,$d){$b=Boot;$x=Svc;$pb=Protected;$ss=@();$c=[double](Get-Process -Id $PID).TotalProcessorTime.TotalMilliseconds;$cnt=[int][math]::Ceiling($SampleSeconds/[double]$SampleIntervalSeconds);for($i=0;$i-lt$cnt;$i++){$ss+=Sys;if($i-lt$cnt-1){sleep $SampleIntervalSeconds}};$y=Svc;$cpu=$null;if($x.process-and$y.process-and$x.process.pid-eq$y.process.pid){$cpu=$y.process.cpuMs-$x.process.cpuMs};[ordered]@{schema=1;experiment='EXP-075';phase=$ph;ordinal=$n;bootUtc=$b.ToString('o');capturedUtc=(Get-Date).ToUniversalTime().ToString('o');system=@{cpuMedianPercent=Med @($ss.cpu);cpuMadPercent=Mad @($ss.cpu);diskMedianBytesPerSec=Med @($ss.disk);diskMadBytesPerSec=Mad @($ss.disk)};service=@{before=$x;after=$y;cpuDeltaMs=$cpu;startedDuringSample=(!$x.process-and$y.process)};protected=@{before=$pb;after=Protected};functional=@{hpServiceScanDemandStart=$null;hpInsightsHealth=$null;networkReadiness=$null};instrumentation=@{collectorCpuDeltaMs=([double](Get-Process -Id $PID).TotalProcessorTime.TotalMilliseconds-$c);sampleCount=$ss.Count}}}
function Sum($d){$r=@(Get-ChildItem $d -Filter 'run-*.json'|sort Name|%{RJ $_.FullName});$g=[ordered]@{};foreach($ph in 'Baseline','Treatment'){$a=@($r|?{$_.phase-eq$ph});$g[$ph]=@{runs=$a.Count;cpuMedianPercent=@{median=Med @($a.system.cpuMedianPercent);mad=Mad @($a.system.cpuMedianPercent)};diskMedianBytesPerSec=@{median=Med @($a.system.diskMedianBytesPerSec);mad=Mad @($a.system.diskMedianBytesPerSec)};serviceCpuDeltaMs=@{median=Med @($a.service.cpuDeltaMs);mad=Mad @($a.service.cpuDeltaMs)}}};$s=[ordered]@{schema=1;experiment='EXP-075';generatedUtc=(Get-Date).ToUniversalTime().ToString('o');classification='inconclusive';groups=$g;limitations=@('HP Service Scan demand-start and HP Insights health require physical functional validation')};WJ (P $d).Summary $s;$s}
function Task($d){$a=New-ScheduledTaskAction -Execute (Get-Command powershell.exe).Source -Argument "-NoProfile -ExecutionPolicy Bypass -File `"$PSCommandPath`" -Action Continue -RunDirectory `"$d`" -EvidenceRoot `"$EvidenceRoot`" -ProviderPath `"$ProviderPath`"";$u=[Security.Principal.WindowsIdentity]::GetCurrent().Name;$t=New-ScheduledTaskTrigger -AtLogOn -User $u;$pr=New-ScheduledTaskPrincipal -UserId $u -LogonType Interactive -RunLevel Highest;if($PSCmdlet.ShouldProcess($TaskName,'Register continuation task')){Register-ScheduledTask -TaskName $TaskName -Action $a -Trigger $t -Principal $pr -Force|Out-Null}};function Untask{if(Get-ScheduledTask -TaskName $TaskName -EA SilentlyContinue){Unregister-ScheduledTask $TaskName -Confirm:$false}};function Reboot{if($AllowAutomaticReboot){Restart-Computer -Force}else{'Reboot required; collection resumes at next logon.'}}
Elev;if(-not(Test-Path $ProviderPath)){throw 'Provider missing'};switch($Action){'Start'{Dir $EvidenceRoot;if(Test-Path $ActivePointer){throw 'Active EXP-075 run exists'};$ck=Prov Check $EvidenceRoot;Prov DryRun $EvidenceRoot|Out-Null;if(-not$ck.Support.Supported){throw 'Provider support check failed'};$d=Join-Path $EvidenceRoot ((Get-Date).ToUniversalTime().ToString('yyyyMMdd-HHmmss'));Dir $d;Prov Capture $d|Out-Null;WJ (P $d).State @{schema=1;phase='Baseline';completedRuns=0;runsPerArm=$RunsPerArm;lastBootUtc=$null};WJ $ActivePointer @{runDirectory=$d};Task $d;Reboot}'Continue'{$d=RD;$p=P $d;$s=RJ $p.State;$boot=(Boot).ToString('o');if($s.lastBootUtc-eq$boot){throw 'Duplicate collection from same boot refused'};if($s.phase-eq'Treatment'){Prov VerifyReboot $d|Out-Null};$n=[int]$s.completedRuns+1;WJ (Join-Path $d ("run-{0}-{1:D2}.json"-f$s.phase,$n)) (Collect $s.phase $n $d);$s.completedRuns=$n;$s.lastBootUtc=$boot;if($n-ge[int]$s.runsPerArm){if($s.phase-eq'Baseline'){$s.phase='Treatment';$s.completedRuns=0;Prov Apply $d|Out-Null}else{Prov Rollback $d|Out-Null;Sum $d|Out-Null;Untask;Remove-Item $ActivePointer -Force;WJ $p.State $s;return RJ $p.Summary}};WJ $p.State $s;Reboot}'Status'{if(Test-Path $ActivePointer){RJ (P (RD)).State}else{[pscustomobject]@{active=$false}}}'Summarize'{Sum (RD)}'Stop'{$d=RD;Prov Rollback $d|Out-Null;Untask;Remove-Item $ActivePointer -Force -EA SilentlyContinue;[pscustomobject]@{stopped=$true;runDirectory=$d}}}